PREFIX eno: <http://example.org/ontology/energy#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?deposit ?year ?month ?extractedGas ?producedOilEquivalents ?producedCondensate
WHERE {
  ?prod a eno:DepositMonthlyProduction ;
        eno:outputForDeposit ?deposit ;
        eno:outputYear ?year ;
        eno:productionMonth ?month ;
        eno:extractedGas ?extractedGas ;
        eno:producedOilEquivalents ?producedOilEquivalents ;
        eno:producedCondensate ?producedCondensate .
}
ORDER BY DESC(?year) DESC(?month)
LIMIT 20

UNDER03_agentic_grep_00abdda5.gt_sparql:
PREFIX eno: <http://example.org/ontology/energy#>
SELECT ?field ?fieldName ?year ?oil ?gas WHERE {
    ?prod a eno:AnnualDepositOutput .
    ?field a eno:Deposit .
    ?prod eno:outputForDeposit ?field .
    ?prod eno:outputYear ?year .
    FILTER(?year >= 2010)
    OPTIONAL { ?prod eno:extractedCrude ?oil }
    OPTIONAL { ?prod eno:extractedGas ?gas }
    OPTIONAL { ?field eno:designation ?fieldName }
}
ORDER BY DESC(?year)

